import React,{ useRef, useState, useEffect } from 'react';
import { IconClose } from '@douyinfe/semi-icons';
import './ImageAnnotator.css';
import { TagInput,Button } from '@douyinfe/semi-ui';
function DataAnnotator({ dataArray, onClose }) {
    const [htmlString, setHtmlString] = useState(` `);
    const [tableData, setTableData] = useState([]) ;
    const [certificateData, setCertificateData] = useState([]) ;
    const [table, setTable] = useState([]) ;
    const [markTable, setMarkTable] = useState([]);
    const [answer, setAnswer] = useState('');
    const [showText, setShowText] = useState(false);
    const parseTableHtml = (htmlString) => {
        const parser = new DOMParser();
        const doc = parser.parseFromString(htmlString, 'text/html');
        const rows = doc.querySelectorAll('tbody tr');
        const data = [];
      
        rows.forEach(row => {
          const cells = row.querySelectorAll('td');
          const rowData = Array.from(cells).map(cell => cell.textContent);
          data.push(rowData);
        });
      
        return data;
    };
    const handleClick = () => {
        setAnswer("项目数量为2,符合要求,但两个项目的内存均存在偏差,成熟度等级为3级,不符合要求。")
        setShowText(true)
    };
    useEffect(() => {
        let dataText = dataArray.map((element) => {
            let data = [];
            element.data.forEach((item,index) => {
                
                    let temp = {
                        text: item.text,
                        type: item.type
                    };
                    data.push(temp);
                
            });
            return data;
        });

        fetch('https://capital-sharply-bison.ngrok-free.app/saveData', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(dataText)
        })
        .then(response => {
            if (!response.ok) {
                throw new Error(`HTTP error! Status: ${response.status}`);
            }
            return response.json();
        })
        .then(data => {
            console.log('数据成功发送至后端，并得到响应:', data);
            setHtmlString(data['table']);
            setTableData(data['data']);
            setCertificateData(data['certificate']);
            console.log(parseTableHtml(data['table']));
            setTable(parseTableHtml(data['table']));
            var temp = parseTableHtml(data['table']);
            data['data'].forEach((element,index) => {
                if(element['name'] == -1){
                    temp[index+1][1] = -1;
                }
                if(element['place'] != temp[index+1][2]){
                    temp[index+1][2] = -1;
                }
                if(element['people'] != temp[index+1][3]){
                    temp[index+1][3] = -1;
                }
                if(element['合同价格'] == -1){
                    temp[index+1][4] = -1;
                }
                if(element['投标日期'] == -1){
                    temp[index+1][5] = -1;
                }
                if(element['概要说明'] == -1){
                    temp[index+1][6] = -1;
                }
            });
            setMarkTable(temp);
        })
        .catch(error => {
            console.error('发送数据至后端时发生错误:', error);
        });
    }, [dataArray]); // Only re-run the effect if dataArray changes
    
    return (
        <div className="image-annotator-popup" style={{  width: '600px' }}>
            <div 
                style={{
                    padding: '0',
                    fontSize: '1.2em',
                    lineHeight: '1em',
                    marginTop: '0',
                    marginBottom: '0',
                    fontWeight: '200',
                    textAlign: 'center',
                }}>
                数据解析
                <button
                    className="close-button"
                    onClick={onClose}
                >
                    <IconClose />
                </button>
            </div>
            <hr style={{ 
              border: 'none', 
              borderBottom: '1px solid grey', 
              height: '0',
              // marginTop: '10px', 
              // marginBottom: '15px' 
              }} />
              <div style={{ padding: '10px',height:  '300px', overflow: 'auto' }}>
              {table.length > 0 ? (
              <table border="1" cellPadding="10" cellSpacing="0" style={{ borderCollapse: 'collapse' }}>
                <thead>
                    <tr>
                    {table[0].map((column, index) => (
                        <th key={index}>{column}</th>
                    ))}
                    </tr>
                </thead>
                <tbody>
                    {table.slice(1).map((project, rowIndex) => ( // 从第二行开始渲染数据
                    <tr key={rowIndex}>
                        {project.map((cell, cellIndex) => (
                        <td 
                            key={cellIndex} 
                            style={{ backgroundColor: markTable[rowIndex+1][cellIndex] === -1 ? 'lightcoral' : 'transparent' }}
                        >
                            {cell}
                        </td>
                        ))}
                    </tr>
                    ))}
                </tbody>
                </table>
              ) : (
                <p>Loading data...</p>
              )}
              </div>
              <hr style={{ 
              border: 'none', 
              borderBottom: '2px solid grey', 
              height: '0',
              // marginTop: '10px', 
              // marginBottom: '15px' 
              }} />
              <TagInput
                    placeholder='请输入...'
                    onChange={v => console.log(v)}
                />
                <div style={{ textAlign: 'center', marginTop: 10 }}>
                    <Button onClick={handleClick}>
                        生成结论
                    </Button>
                </div>
                {showText && (
                    <div style={{ 
                        marginTop: 10, 
                        fontSize: '20px', 
                        fontWeight: 'bold', 
                        color: 'rgba(var(--semi-blue-6), 1)' 
                      }}>
                        {answer}
                      </div>
                )}
              <hr style={{ 
              border: 'none', 
              borderBottom: '2px solid grey', 
              height: '0',
              // marginTop: '10px', 
              // marginBottom: '15px' 
              }} />
              <div style={{ padding: '10px', height:  '200px', overflow: 'auto' }}>
                {tableData.map((project, index) => (
                    <div key={index}>
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
                            <div>
                                <div>项目名称: {project.name}</div>
                                <div>项目地点: 
                                {project['place'] !== table[index+1][2] ? (
                                    
                                    <span style={{ color: 'red' }}>{project['place']}(信息不匹配)</span>
                                    
                                ) : (
                                    project['place']
                                )}
                                </div>
                                <div>项目法人: 
                                {project['people'] !== table[index+1][3] ? (
                                    <span style={{ color: 'red' }}>{project['people']}(信息不匹配)</span>
                                ) : (
                                    project['people']
                                )}
                                </div>
                                <div>投标日期: 
                                {project['投标日期'] === -1 ? (
                                    <span style={{ color: 'red' }}>未查询到相关信息</span>
                                ) : (
                                    project['投标日期']
                                )}
                                </div>
                                <div>概要说明: 
                                {project['概要说明'] === -1 ? (
                                    <span style={{ color: 'red' }}>未查询到相关信息</span>
                                ) : (
                                    project['概要说明']
                                )}
                                </div>
                            </div>
                            <div>
                                <div>发票编号: 
                                {project['发票编号'] === -1 ? (
                                    <span style={{ color: 'red' }}>未查询到相关信息</span>
                                ) : (
                                    project['发票编号']
                                )}
                                </div>
                                <div>起始页面: 
                                {project.beginPage === -1 ? (
                                    <span style={{ color: 'red' }}>未查询到相关信息</span>
                                ) : (
                                    project.beginPage
                                )}
                                </div>
                                <div>合同开始页面: 
                                {project.billPage === -1 ? (
                                    <span style={{ color: 'red' }}>未查询到相关信息</span>
                                ) : (
                                    project.billPage
                                )}
                                </div>
                                <div>结束页面: 
                                {project.endPage === -1 ? (
                                    <span style={{ color: 'red' }}>未查询到相关信息</span>
                                ) : (
                                    project.endPage
                                )}
                                </div>
                            </div>
                        </div>
                        <hr style={{ 
                          border: 'none', 
                          borderBottom: '1px solid grey', 
                          height: '0',
                          }} />
                    </div>
                ))}
            </div>
            <hr style={{ 
              border: 'none', 
              borderBottom: '2px solid grey', 
              height: '0',
              // marginTop: '10px', 
              // marginBottom: '15px' 
              }} />
            <div style={{ padding: '10px', height: '200px', overflow: 'auto' }}>
                {certificateData.map((project, index) => (
                    <div key={index}>
                        <div>证书所在页面: {project['证书所在页面']}</div>
                        {project['证书等级'] === -1 ? (
                            <div>
                            <div>标准编号: {project['标准编号']}</div>
                            <div>证书编码: {project['证书编码']}</div>
                            <div>认证范围: {project['认证范围']}</div>
                            <div>{project['发证日期']}</div>
                            <div>{project['有效期至']}</div>
                            </div>
                        ) : (
                            <div>
                            <div>成熟度等级: CMMI Maturity Level 3</div>
                            </div>
                        )}
                        <hr style={{ 
                          border: 'none', 
                          borderBottom: '1px solid grey', 
                          height: '0',
                          }} />
                    </div>
                ))}
            </div>
        </div>
    );
}

export default DataAnnotator;
